export const settingsCoverage = {
    checkedAt: "2026-10-11",
    appBaseline: "1.1.28",
    complete: false,
    boundary: "Documented desktop app controls, shared formats, and app-supported managed policy. Not an app settings-file schema.",
    gaps: [
        "No published complete desktop settings or experiments schema.",
        "Release-note experiments do not establish current visibility, eligibility, or defaults.",
        "Imported CLI formats do not establish full app field support or precedence.",
        "Defaults, reload behavior, and policy enforcement require installed-build verification where unspecified.",
    ],
};

function entry(id, component, label, location, values, defaultValue, source, options = {}) {
    return {
        id, component, label, location, values, default: defaultValue,
        scope: "user", status: "documented", evidence: "app",
        sources: [source], requires: [], conflicts: [], caveats: [],
        ...options,
    };
}

